    if ($q->count > 1) {
        $repeated[] = $q;
    }
}
$events = $logs->events;
return ['profile' => $profile, 'repeatedQueries' => $repeated, 'events' => $events];

$reqs = $tools->call('perf_requests', []);
$beforeItem = null;
$afterItem = null;
foreach ($reqs->items as $item) {
    if ($item->route === 'catalog_naive' && $item->variant === 'before') {
        $beforeItem = $item;
    }
    if ($item->route === 'catalog_joined' && $item->variant === 'after') {
        $afterItem = $item;
    }
}
if (!$beforeItem || !$afterItem) {
    return ['error' => 'Required request items not found'];
}
$beforeProfile = $tools->call('perf_profile', ['requestId' => $beforeItem->requestId]);
$beforeLogs = $tools->call('perf_logs', ['requestId' => $beforeItem->requestId]);
$afterProfile = $tools->call('perf_profile', ['requestId' => $afterItem->requestId]);
$afterLogs = $tools->call('perf_logs', ['requestId' => $afterItem->requestId]);
$sameOutput = ($beforeProfile->outputSha256 === $afterProfile->outputSha256);
$queriesSaved = $beforeProfile->queryCount - $afterProfile->queryCount;
return [
    'before' => [
        'profile' => $beforeProfile,
        'events' => $beforeLogs->events,
    ],
    'after' => [
        'profile' => $afterProfile,
        'events' => $afterLogs->events,
    ],
    'sameOutput' => $sameOutput,
    'queriesSaved' => $queriesSaved,
];

