/* PHP code to fetch slowest baseline request and related data */
$requests = $tools->call('perf_requests', []);
if (isset($requests->error)) { return $requests; }
$items = $requests->items;
$baseline = null;
foreach ($items as $item) {
    if (!in_array($item->variant, ['before', 'control'])) continue;
    if ($baseline === null || $item->durationMs > $baseline->durationMs) {
        $baseline = $item;
    }
}
if ($baseline === null) {
    return (object)[
        'error' => 'No baseline request found'
    ];
}
$reqId = $baseline->requestId;
$profile = $tools->call('perf_profile', ['requestId' => $reqId]);
$logs = $tools->call('perf_logs', ['requestId' => $reqId]);
// Extract repeated queries (count > 1)
$repeated = [];
if (isset($profile->queries) && is_array($profile->queries)) {
    foreach ($profile->queries as $q) {
        if ($q->count > 1) {
            $repeated[] = (object)[
                'fingerprint' => $q->fingerprint,
                'count' => $q->count,
                'durationMs' => $q->durationMs
            ];
        }
    }
}
// Events from logs
$events = [];
if (isset($logs->events) && is_array($logs->events)) {
    foreach ($logs->events as $e) {
        $events[] = (object)[
            'event' => $e->event,
            'level' => $e->level,
            'count' => $e->count
        ];
    }
}
return (object)[
    'profile' => $profile,
    'repeatedQueries' => $repeated,
    'events' => $events
];

